-- Procedure: game_player_balls_in_play_heatmaps
INSERT INTO game_player_balls_in_play_heatmaps(
    gamePk,
    atBatIndex,
    battingTeamId,
    batterId,
    batSide,
    pitchingTeamId,
    pitcherId,
    pitchHand,
    menOnBase,
    -- HM4
    HM4_LF1_X1B,
    HM4_LF1_X2B,
    HM4_LF1_X3B,
    HM4_LF1_HR,
    HM4_LF1_H,
    HM4_LF2_X1B,
    HM4_LF2_X2B,
    HM4_LF2_X3B,
    HM4_LF2_HR,
    HM4_LF2_H,
    HM4_RF1_X1B,
    HM4_RF1_X2B,
    HM4_RF1_X3B,
    HM4_RF1_HR,
    HM4_RF1_H,
    HM4_RF2_X1B,
    HM4_RF2_X2B,
    HM4_RF2_X3B,
    HM4_RF2_HR,
    HM4_RF2_H,
    -- HM8
    HM8_LF1_X1B,
    HM8_LF1_X2B,
    HM8_LF1_X3B,
    HM8_LF1_HR,
    HM8_LF1_H,
    HM8_LF2_X1B,
    HM8_LF2_X2B,
    HM8_LF2_X3B,
    HM8_LF2_HR,
    HM8_LF2_H,
    HM8_LF3_X1B,
    HM8_LF3_X2B,
    HM8_LF3_X3B,
    HM8_LF3_HR,
    HM8_LF3_H,
    HM8_LF4_X1B,
    HM8_LF4_X2B,
    HM8_LF4_X3B,
    HM8_LF4_HR,
    HM8_LF4_H,
    HM8_RF1_X1B,
    HM8_RF1_X2B,
    HM8_RF1_X3B,
    HM8_RF1_HR,
    HM8_RF1_H,
    HM8_RF2_X1B,
    HM8_RF2_X2B,
    HM8_RF2_X3B,
    HM8_RF2_HR,
    HM8_RF2_H,
    HM8_RF3_X1B,
    HM8_RF3_X2B,
    HM8_RF3_X3B,
    HM8_RF3_HR,
    HM8_RF3_H,
    HM8_RF4_X1B,
    HM8_RF4_X2B,
    HM8_RF4_X3B,
    HM8_RF4_HR,
    HM8_RF4_H
  )
SELECT
  gamePk,
  atBatIndex,
  battingTeamId,
  batterId,
  batSide,
  pitchingTeamId,
  pitcherId,
  pitchHand,
  menOnBase,
  SUM(CASE WHEN event = 'Single' AND HM4 = 'LF1' THEN 1 ELSE 0 END ) HM4_LF1_X1B,
  SUM(CASE WHEN event = 'Double' AND HM4 = 'LF1' THEN 1 ELSE 0 END ) HM4_LF1_X2B,
  SUM(CASE WHEN event = 'Triple' AND HM4 = 'LF1' THEN 1 ELSE 0 END ) HM4_LF1_X3B,
  SUM(CASE WHEN event = 'Home Run' AND HM4 = 'LF1' THEN 1 ELSE 0 END ) HM4_LF1_HR,
  SUM(CASE WHEN event In ( 'Single', 'Double', 'Triple', 'Home Run' ) AND HM4 = 'LF1' THEN 1 ELSE 0 END ) HM4_LF1_H,
  SUM(CASE WHEN event = 'Single' AND HM4 = 'LF2' THEN 1 ELSE 0 END ) HM4_LF2_X1B,
  SUM(CASE WHEN event = 'Double' AND HM4 = 'LF2' THEN 1 ELSE 0 END ) HM4_LF2_X2B,
  SUM(CASE WHEN event = 'Triple' AND HM4 = 'LF2' THEN 1 ELSE 0 END ) HM4_LF2_X3B,
  SUM(CASE WHEN event = 'Home Run' AND HM4 = 'LF2' THEN 1 ELSE 0 END ) HM4_LF2_HR,
  SUM(CASE WHEN event In ( 'Single', 'Double', 'Triple', 'Home Run' ) AND HM4 = 'LF2' THEN 1 ELSE 0 END ) HM4_LF2_H,
  SUM(CASE WHEN event = 'Single' AND HM4 = 'RF1' THEN 1 ELSE 0 END ) HM4_RF1_X1B,
  SUM(CASE WHEN event = 'Double' AND HM4 = 'RF1' THEN 1 ELSE 0 END ) HM4_RF1_X2B,
  SUM(CASE WHEN event = 'Triple' AND HM4 = 'RF1' THEN 1 ELSE 0 END ) HM4_RF1_X3B,
  SUM(CASE WHEN event = 'Home Run' AND HM4 = 'RF1' THEN 1 ELSE 0 END ) HM4_RF1_HR,
  SUM(CASE WHEN event In ( 'Single', 'Double', 'Triple', 'Home Run' ) AND HM4 = 'RF1' THEN 1 ELSE 0 END ) HM4_RF1_H,
  SUM(CASE WHEN event = 'Single' AND HM4 = 'RF2' THEN 1 ELSE 0 END ) HM4_RF2_X1B,
  SUM(CASE WHEN event = 'Double' AND HM4 = 'RF2' THEN 1 ELSE 0 END ) HM4_RF2_X2B,
  SUM(CASE WHEN event = 'Triple' AND HM4 = 'RF2' THEN 1 ELSE 0 END ) HM4_RF2_X3B,
  SUM(CASE WHEN event = 'Home Run' AND HM4 = 'RF2' THEN 1 ELSE 0 END ) HM4_RF2_HR,
  SUM(CASE WHEN event In ( 'Single', 'Double', 'Triple', 'Home Run' ) AND HM4 = 'RF2' THEN 1 ELSE 0 END ) HM4_RF2_H,
  -- HM8: 8 octants
  SUM(CASE WHEN event = 'Single' AND HM8 = 'LF1' THEN 1 ELSE 0 END ) HM8_LF1_X1B,
  SUM(CASE WHEN event = 'Double' AND HM8 = 'LF1' THEN 1 ELSE 0 END ) HM8_LF1_X2B,
  SUM(CASE WHEN event = 'Triple' AND HM8 = 'LF1' THEN 1 ELSE 0 END ) HM8_LF1_X3B,
  SUM(CASE WHEN event = 'Home Run' AND HM8 = 'LF1' THEN 1 ELSE 0 END ) HM8_LF1_HR,
  SUM(CASE WHEN event In ( 'Single', 'Double', 'Triple', 'Home Run' ) AND HM8 = 'LF1' THEN 1 ELSE 0 END ) HM8_LF1_H,
  SUM(CASE WHEN event = 'Single' AND HM8 = 'LF2' THEN 1 ELSE 0 END ) HM8_LF2_X1B,
  SUM(CASE WHEN event = 'Double' AND HM8 = 'LF2' THEN 1 ELSE 0 END ) HM8_LF2_X2B,
  SUM(CASE WHEN event = 'Triple' AND HM8 = 'LF2' THEN 1 ELSE 0 END ) HM8_LF2_X3B,
  SUM(CASE WHEN event = 'Home Run' AND HM8 = 'LF2' THEN 1 ELSE 0 END ) HM8_LF2_HR,
  SUM(CASE WHEN event In ( 'Single', 'Double', 'Triple', 'Home Run' ) AND HM8 = 'LF2' THEN 1 ELSE 0 END ) HM8_LF2_H,
  SUM(CASE WHEN event = 'Single' AND HM8 = 'LF3' THEN 1 ELSE 0 END ) HM8_LF3_X1B,
  SUM(CASE WHEN event = 'Double' AND HM8 = 'LF3' THEN 1 ELSE 0 END ) HM8_LF3_X2B,
  SUM(CASE WHEN event = 'Triple' AND HM8 = 'LF3' THEN 1 ELSE 0 END ) HM8_LF3_X3B,
  SUM(CASE WHEN event = 'Home Run' AND HM8 = 'LF3' THEN 1 ELSE 0 END ) HM8_LF3_HR,
  SUM(CASE WHEN event In ( 'Single', 'Double', 'Triple', 'Home Run' ) AND HM8 = 'LF3' THEN 1 ELSE 0 END ) HM8_LF3_H,
  SUM(CASE WHEN event = 'Single' AND HM8 = 'LF4' THEN 1 ELSE 0 END ) HM8_LF4_X1B,
  SUM(CASE WHEN event = 'Double' AND HM8 = 'LF4' THEN 1 ELSE 0 END ) HM8_LF4_X2B,
  SUM(CASE WHEN event = 'Triple' AND HM8 = 'LF4' THEN 1 ELSE 0 END ) HM8_LF4_X3B,
  SUM(CASE WHEN event = 'Home Run' AND HM8 = 'LF4' THEN 1 ELSE 0 END ) HM8_LF4_HR,
  SUM(CASE WHEN event In ( 'Single', 'Double', 'Triple', 'Home Run' ) AND HM8 = 'LF4' THEN 1 ELSE 0 END ) HM8_LF4_H,
  SUM(CASE WHEN event = 'Single' AND HM8 = 'RF1' THEN 1 ELSE 0 END ) HM8_RF1_X1B,
  SUM(CASE WHEN event = 'Double' AND HM8 = 'RF1' THEN 1 ELSE 0 END ) HM8_RF1_X2B,
  SUM(CASE WHEN event = 'Triple' AND HM8 = 'RF1' THEN 1 ELSE 0 END ) HM8_RF1_X3B,
  SUM(CASE WHEN event = 'Home Run' AND HM8 = 'RF1' THEN 1 ELSE 0 END ) HM8_RF1_HR,
  SUM(CASE WHEN event In ( 'Single', 'Double', 'Triple', 'Home Run' ) AND HM8 = 'RF1' THEN 1 ELSE 0 END ) HM8_RF1_H,
  SUM(CASE WHEN event = 'Single' AND HM8 = 'RF2' THEN 1 ELSE 0 END ) HM8_RF2_X1B,
  SUM(CASE WHEN event = 'Double' AND HM8 = 'RF2' THEN 1 ELSE 0 END ) HM8_RF2_X2B,
  SUM(CASE WHEN event = 'Triple' AND HM8 = 'RF2' THEN 1 ELSE 0 END ) HM8_RF2_X3B,
  SUM(CASE WHEN event = 'Home Run' AND HM8 = 'RF2' THEN 1 ELSE 0 END ) HM8_RF2_HR,
  SUM(CASE WHEN event In ( 'Single', 'Double', 'Triple', 'Home Run' ) AND HM8 = 'RF2' THEN 1 ELSE 0 END ) HM8_RF2_H,
  SUM(CASE WHEN event = 'Single' AND HM8 = 'RF3' THEN 1 ELSE 0 END ) HM8_RF3_X1B,
  SUM(CASE WHEN event = 'Double' AND HM8 = 'RF3' THEN 1 ELSE 0 END ) HM8_RF3_X2B,
  SUM(CASE WHEN event = 'Triple' AND HM8 = 'RF3' THEN 1 ELSE 0 END ) HM8_RF3_X3B,
  SUM(CASE WHEN event = 'Home Run' AND HM8 = 'RF3' THEN 1 ELSE 0 END ) HM8_RF3_HR,
  SUM(CASE WHEN event In ( 'Single', 'Double', 'Triple', 'Home Run' ) AND HM8 = 'RF3' THEN 1 ELSE 0 END ) HM8_RF3_H,
  SUM(CASE WHEN event = 'Single' AND HM8 = 'RF4' THEN 1 ELSE 0 END ) HM8_RF4_X1B,
  SUM(CASE WHEN event = 'Double' AND HM8 = 'RF4' THEN 1 ELSE 0 END ) HM8_RF4_X2B,
  SUM(CASE WHEN event = 'Triple' AND HM8 = 'RF4' THEN 1 ELSE 0 END ) HM8_RF4_X3B,
  SUM(CASE WHEN event = 'Home Run' AND HM8 = 'RF4' THEN 1 ELSE 0 END ) HM8_RF4_HR,
  SUM(CASE WHEN event In ( 'Single', 'Double', 'Triple', 'Home Run' ) AND HM8 = 'RF4' THEN 1 ELSE 0 END ) HM8_RF4_H
FROM atbats
WHERE ( gamePk, atBatIndex ) NOT IN ( SELECT gamePk, atBatIndex
                                      FROM game_player_balls_in_play_heatmaps
                                    )
GROUP BY
  1, 2, 3, 4, 5, 6, 7, 8, 9;


-- Stats from pitching
UPDATE game_player_balls_in_play_heatmaps
SET
    -- HM4 zone counts
    HM4_FHP      = (SELECT SUM(CASE WHEN HM4 = 'FHP' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_FLF      = (SELECT SUM(CASE WHEN HM4 = 'FLF' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_FRF      = (SELECT SUM(CASE WHEN HM4 = 'FRF' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF1      = (SELECT SUM(CASE WHEN HM4 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF2      = (SELECT SUM(CASE WHEN HM4 = 'RF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF1      = (SELECT SUM(CASE WHEN HM4 = 'LF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF2      = (SELECT SUM(CASE WHEN HM4 = 'LF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    -- HM4 RF1 trajectories
    HM4_RF1_FB   = (SELECT SUM(CASE WHEN trajectory = 'fly_ball' AND HM4 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF1_GB   = (SELECT SUM(CASE WHEN trajectory = 'ground_ball' AND HM4 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF1_LD   = (SELECT SUM(CASE WHEN trajectory = 'line_drive' AND HM4 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF1_PU   = (SELECT SUM(CASE WHEN trajectory = 'popup' AND HM4 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF1_GBNT = (SELECT SUM(CASE WHEN trajectory = 'bunt_grounder' AND HM4 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF1_PUB  = (SELECT SUM(CASE WHEN trajectory = 'bunt_popup' AND HM4 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF1_LDB  = (SELECT SUM(CASE WHEN trajectory = 'bunt_line_drive' AND HM4 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    -- HM4 RF2 trajectories
    HM4_RF2_FB   = (SELECT SUM(CASE WHEN trajectory = 'fly_ball' AND HM4 = 'RF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF2_GB   = (SELECT SUM(CASE WHEN trajectory = 'ground_ball' AND HM4 = 'RF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF2_LD   = (SELECT SUM(CASE WHEN trajectory = 'line_drive' AND HM4 = 'RF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF2_PU   = (SELECT SUM(CASE WHEN trajectory = 'popup' AND HM4 = 'RF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF2_GBNT = (SELECT SUM(CASE WHEN trajectory = 'bunt_grounder' AND HM4 = 'RF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF2_PUB  = (SELECT SUM(CASE WHEN trajectory = 'bunt_popup' AND HM4 = 'RF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_RF2_LDB  = (SELECT SUM(CASE WHEN trajectory = 'bunt_line_drive' AND HM4 = 'RF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    -- HM4 LF1 trajectories
    HM4_LF1_FB   = (SELECT SUM(CASE WHEN trajectory = 'fly_ball' AND HM4 = 'LF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF1_GB   = (SELECT SUM(CASE WHEN trajectory = 'ground_ball' AND HM4 = 'LF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF1_LD   = (SELECT SUM(CASE WHEN trajectory = 'line_drive' AND HM4 = 'LF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF1_PU   = (SELECT SUM(CASE WHEN trajectory = 'popup' AND HM4 = 'LF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF1_GBNT = (SELECT SUM(CASE WHEN trajectory = 'bunt_grounder' AND HM4 = 'LF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF1_PUB  = (SELECT SUM(CASE WHEN trajectory = 'bunt_popup' AND HM4 = 'LF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF1_LDB  = (SELECT SUM(CASE WHEN trajectory = 'bunt_line_drive' AND HM4 = 'LF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    -- HM4 LF2 trajectories
    HM4_LF2_FB   = (SELECT SUM(CASE WHEN trajectory = 'fly_ball' AND HM4 = 'LF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF2_GB   = (SELECT SUM(CASE WHEN trajectory = 'ground_ball' AND HM4 = 'LF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF2_LD   = (SELECT SUM(CASE WHEN trajectory = 'line_drive' AND HM4 = 'LF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF2_PU   = (SELECT SUM(CASE WHEN trajectory = 'popup' AND HM4 = 'LF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF2_GBNT = (SELECT SUM(CASE WHEN trajectory = 'bunt_grounder' AND HM4 = 'LF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF2_PUB  = (SELECT SUM(CASE WHEN trajectory = 'bunt_popup' AND HM4 = 'LF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM4_LF2_LDB  = (SELECT SUM(CASE WHEN trajectory = 'bunt_line_drive' AND HM4 = 'LF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    -- HM8 zone counts
    HM8_FHP      = (SELECT SUM(CASE WHEN HM4 = 'FHP' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_FLF      = (SELECT SUM(CASE WHEN HM4 = 'FLF' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_FRF      = (SELECT SUM(CASE WHEN HM4 = 'FRF' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_RF1      = (SELECT SUM(CASE WHEN HM8 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_RF2      = (SELECT SUM(CASE WHEN HM8 = 'RF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_RF3      = (SELECT SUM(CASE WHEN HM8 = 'RF3' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_RF4      = (SELECT SUM(CASE WHEN HM8 = 'RF4' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_LF1      = (SELECT SUM(CASE WHEN HM8 = 'LF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_LF2      = (SELECT SUM(CASE WHEN HM8 = 'LF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_LF3      = (SELECT SUM(CASE WHEN HM8 = 'LF3' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_LF4      = (SELECT SUM(CASE WHEN HM8 = 'LF4' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    -- HM8 RF1 trajectories
    HM8_RF1_FB   = (SELECT SUM(CASE WHEN trajectory = 'fly_ball' AND HM8 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_RF1_GB   = (SELECT SUM(CASE WHEN trajectory = 'ground_ball' AND HM8 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_RF1_LD   = (SELECT SUM(CASE WHEN trajectory = 'line_drive' AND HM8 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_RF1_PU   = (SELECT SUM(CASE WHEN trajectory = 'popup' AND HM8 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_RF1_GBNT = (SELECT SUM(CASE WHEN trajectory = 'bunt_grounder' AND HM8 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_RF1_PUB  = (SELECT SUM(CASE WHEN trajectory = 'bunt_popup' AND HM8 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    HM8_RF1_LDB  = (SELECT SUM(CASE WHEN trajectory = 'bunt_line_drive' AND HM8 = 'RF1' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
    -- HM8 RF2 trajectories
    HM8_RF2_FB   = (SELECT SUM(CASE WHEN trajectory = 'fly_ball' AND HM8 = 'RF2' THEN 1 ELSE 0 END) FROM pitches p WHERE game_player_balls_in_play_heatmaps.gamePk = p.gamePk AND game_player_balls_in_play_heatmaps.atBatIndex = p.atBatIndex),
